CREATE OR REPLACE FUNCTION public.get_intent_to_value_time(p_capability uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE c jsonb; intent_at timestamptz; value_at timestamptz; refs jsonb; BEGIN c:=public.evidence_chain(p_capability);
SELECT min(coalesce(nullif(o->'body'->'confirmation'->>'at','')::timestamptz,nullif(o->'body'->'confirmation'->>'confirmed_at','')::timestamptz,nullif(o->'body'->>'confirmed_at','')::timestamptz)) INTO intent_at FROM jsonb_array_elements(c->'links') l CROSS JOIN LATERAL jsonb_array_elements(l->'objects') o WHERE l->>'link'='behavior' AND o->>'state' NOT IN('draft','proposed','rejected','superseded');
IF intent_at IS NULL THEN SELECT min(coalesce(nullif(o->'body'->>'effective_from','')::timestamptz,(o->>'created_at')::timestamptz)) INTO intent_at FROM jsonb_array_elements(c->'links') l CROSS JOIN LATERAL jsonb_array_elements(l->'objects') o WHERE l->>'link'='decision'; END IF;
SELECT min((o->'body'->>'realised_at')::timestamptz) INTO value_at FROM jsonb_array_elements(c->'links') l CROSS JOIN LATERAL jsonb_array_elements(l->'objects') o WHERE l->>'link'='value' AND o->'body'->>'adapter_mode' IS DISTINCT FROM 'simulated' AND coalesce(o->'body'->'provenance'->>'simulated','false')<>'true' AND jsonb_array_length(coalesce(o->'body'->'source_evidence','[]'))>0 AND EXISTS(SELECT 1 FROM jsonb_array_elements(c->'links') pl CROSS JOIN LATERAL jsonb_array_elements(pl->'objects') po WHERE pl->>'link'='outcome' AND po->>'type'='ProductionOutcome' AND po->'body'->>'adapter_mode' IS DISTINCT FROM 'simulated' AND coalesce(po->'body'->'provenance'->>'simulated','false')<>'true') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(o->'body'->'source_evidence','[]')) e WHERE NOT EXISTS(SELECT 1 FROM public.objects src WHERE src.id::text=e AND NOT src.is_tombstone AND src.lifecycle_state NOT IN('draft','proposed','rejected','superseded') AND src.body->>'adapter_mode' IS DISTINCT FROM 'simulated' AND coalesce(src.body->'provenance'->>'simulated','false')<>'true'));
SELECT coalesce(jsonb_agg(jsonb_build_object('id',o->>'id','ref',o->>'ref','type',o->>'type')),'[]') INTO refs FROM jsonb_array_elements(c->'links') l CROSS JOIN LATERAL jsonb_array_elements(l->'objects') o WHERE l->>'link' IN('behavior','decision','outcome','value');
RETURN jsonb_build_object('capability_id',p_capability,'hours',public.phase10_elapsed_hours(intent_at,value_at),'confirmed_at',intent_at,'realised_at',value_at,'status',CASE WHEN intent_at IS NULL OR value_at IS NULL THEN 'NO_LIVE_EVIDENCE' WHEN value_at<intent_at THEN 'INVALID_TEMPORAL_EVIDENCE' ELSE 'measured' END,'evidence',refs); END $$;
CREATE OR REPLACE FUNCTION public.phase10_action_ratios() RETURNS jsonb LANGUAGE sql STABLE SET search_path=public AS $$ WITH s AS(SELECT count(*) n,count(*) FILTER(WHERE mutating_actions>0) a,count(*) FILTER(WHERE mutating_actions=0 AND reads>0) r FROM public.usage_sessions),cfg AS(SELECT value,status FROM public.canon_settings WHERE key='anti_wiki.action_ratio') SELECT jsonb_build_object('action_pct',100.0*a/nullif(n,0),'read_only_pct',100.0*r/nullif(n,0),'status',CASE WHEN NOT EXISTS(SELECT 1 FROM cfg WHERE status='decided' AND value IS NOT NULL) THEN 'THRESHOLD_UNSET' WHEN n=0 THEN 'NO_EVIDENCE' ELSE 'measured' END,'thresholds',(SELECT value FROM cfg),'evidence',jsonb_build_object('source','usage_sessions','sessions',n)) FROM s $$;
CREATE OR REPLACE FUNCTION public.phase10_measurements() RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE times jsonb; m numeric; BEGIN
SELECT coalesce(jsonb_agg(public.get_intent_to_value_time(o.id)),'[]') INTO times FROM public.objects o WHERE NOT o.is_tombstone AND o.type IN('ComposableCapability','WorkingCapability');
SELECT percentile_cont(0.5) WITHIN GROUP(ORDER BY (t->>'hours')::double precision)::numeric INTO m FROM jsonb_array_elements(times) t WHERE t->>'status'='measured';
RETURN jsonb_build_object('primary',jsonb_build_object('label','Median intent-to-value time','hours',m,'status',CASE WHEN m IS NULL THEN 'NO_LIVE_EVIDENCE' ELSE 'measured' END,'chains',times),
'flow',jsonb_build_object('judgment_latency',coalesce((SELECT jsonb_agg(jsonb_build_object('request_id',r.id,'request_ref',r.human_ref,'decision_id',d.id,'decision_ref',d.human_ref,'hours',public.phase10_elapsed_hours(r.created_at,d.created_at))) FROM public.objects r JOIN public.objects d ON d.body->>'request_ref'=r.id::text WHERE r.type='HumanDecisionRequest' AND d.type='Decision' AND NOT r.is_tombstone AND NOT d.is_tombstone),'[]'),'stage_times',times),
'quality',jsonb_build_object('shadow',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'ref',human_ref,'discrepancy_rate',body->'discrepancy_rate','mode',body->>'adapter_mode')) FROM public.objects WHERE type='ShadowRun' AND NOT is_tombstone),'[]'),'incidents',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'ref',human_ref,'severity',body->>'severity')) FROM public.objects WHERE type='Incident' AND NOT is_tombstone),'[]'),'rollbacks',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'ref',human_ref,'duration',body->'duration')) FROM public.objects WHERE type='Rollback' AND NOT is_tombstone),'[]')),
'value',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'ref',human_ref,'unit',body->>'unit','baseline',body->'baseline','delta',body->'delta','value',body->'value','evidence',body->'source_evidence','mode',body->>'adapter_mode')) FROM public.objects WHERE type='ValueMeasure' AND NOT is_tombstone AND body->>'adapter_mode' IS DISTINCT FROM 'simulated' AND coalesce(body->'provenance'->>'simulated','false')<>'true' AND jsonb_array_length(coalesce(body->'source_evidence','[]'))>0),'[]'),
'capability',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'ref',o.human_ref,'authority',o.authority_level,'dependencies',(SELECT count(*) FROM public.edges e WHERE e.from_id=o.id AND e.verb='depends_on' AND e.retired_at IS NULL),'usage',coalesce((SELECT jsonb_agg(jsonb_build_object('id',u.id,'outcome',u.outcome,'cost',u.cost,'latency_ms',u.latency_ms,'mode',u.adapter_mode)) FROM public.capability_usage u WHERE u.capability_id=o.id),'[]'))) FROM public.objects o WHERE o.type='ComposableCapability' AND NOT o.is_tombstone),'[]'),
'community',jsonb_build_object('reuse',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'capability_id',capability_id,'outcome',outcome,'mode',adapter_mode)) FROM public.capability_usage WHERE adapter_mode='live'),'[]'),'status','PARTIAL: mission and cell evidence arrives in Phase 11'),
'health',jsonb_build_object('action_ratio',public.phase10_action_ratios(),'finding_age',coalesce((SELECT jsonb_agg(jsonb_build_object('finding_id',id,'detector',detector_key,'hours',public.phase10_elapsed_hours(created_at,now()),'state',state)) FROM public.detector_findings WHERE state<>'resolved'),'[]'),'schema',public.phase10_schema_check(),'chain_completeness',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'ref',human_ref,'chain',public.chain_completeness(id))) FROM public.objects WHERE type='ComposableCapability' AND NOT is_tombstone),'[]')),'computed_at',now()); END $$;
REVOKE ALL ON FUNCTION public.phase10_measurements(),public.get_intent_to_value_time(uuid),public.phase10_action_ratios() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.phase10_measurements(),public.get_intent_to_value_time(uuid),public.phase10_action_ratios() TO authenticated,service_role;
ALTER POLICY "read findings" ON public.detector_findings TO authenticated USING ((object_id IS NULL OR EXISTS(SELECT 1 FROM public.objects o WHERE o.id=object_id)) AND (NOT evidence ? 'owner_id' OR evidence->>'owner_id'=auth.uid()::text OR public.has_role(auth.uid(),'steward')) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(evidence->'evidence_refs')='array' THEN evidence->'evidence_refs' ELSE '[]' END) e WHERE NOT EXISTS(SELECT 1 FROM public.objects o WHERE o.id::text=e)));
DO $$ DECLARE ev jsonb; BEGIN ev:=public.thread_phase10_selftest(); IF ev->>'passed'<>'true' THEN RAISE EXCEPTION 'Phase 10 selftest failed: %',ev; END IF; END $$;